#pragma once#include <macros/AutoCloser.h>#include <vector>template<class T>void GetFileToBuffer( LPCSTR pszFile, std::vector<T> &btBuf ){  KAutoCloser<HANDLE> hFile( CreateFile( pszFile,                                        GENERIC_READ,                                        FILE_SHARE_READ,                                        NULL,                                        OPEN_EXISTING,                                        0,                                        NULL),                                        CloseHandle );  if ( hFile ==	INVALID_HANDLE_VALUE	)    return;  DWORD dwSize = GetFileSize( hFile, NULL );  btBuf.resize( dwSize, 0 );  T * pData = &btBuf[0];  DWORD Lr = 0;  ReadFile( hFile, pData, dwSize, &Lr, NULL );}